import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:go_router/go_router.dart';
import '../../../../core/routing/app_routes.dart';import '../../../../core/theme/app_colors.dart';import '../../../../core/theme/app_dimens.dart';import '../../../../core/theme/app_text_styles.dart';import '../../data/models/interested_area_model.dart';import '../providers/interested_area_provider.dart';import '../widgets/interested_area_card.dart';import '../widgets/interested_area_editor.dart';
class InterestedAreasPage extends ConsumerWidget{const InterestedAreasPage({super.key});Future<void> editor(BuildContext context,WidgetRef ref,[InterestedAreaModel? area])async{await showModalBottomSheet(context:context,isScrollControlled:true,useSafeArea:true,backgroundColor:AppColors.surface,builder:(_)=>InterestedAreaEditor(area:area,onSearch:(query,lat,lng)=>ref.read(interestedAreaDataSourceProvider).searchPlaces(query,latitude:lat,longitude:lng),onSave:(name,lat,lng,radius,notify)=>ref.read(interestedAreasProvider.notifier).save(id:area?.id,name:name,latitude:lat,longitude:lng,radiusM:radius,notificationsEnabled:notify)));}
@override Widget build(BuildContext context,WidgetRef ref){final state=ref.watch(interestedAreasProvider);return Scaffold(backgroundColor:AppColors.homeCanvas,appBar:AppBar(title:const Text('Khu vực quan tâm',style:AppTextStyles.titleMedium),backgroundColor:AppColors.homeCanvas),floatingActionButton:FloatingActionButton.extended(onPressed:()=>editor(context,ref),icon:const Icon(Icons.add_location_alt_outlined),label:const Text('Thêm khu vực')),body:state.when(loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:TextButton.icon(onPressed:()=>ref.invalidate(interestedAreasProvider),icon:const Icon(Icons.refresh),label:const Text('Tải lại'))),data:(items)=>RefreshIndicator(onRefresh:()=>ref.refresh(interestedAreasProvider.future),child:items.isEmpty?ListView(children:[SizedBox(height:MediaQuery.sizeOf(context).height*.25),const Icon(Icons.location_searching,size:48,color:AppColors.primary),const SizedBox(height:AppDimens.spacingMd),Text('Chưa có khu vực quan tâm',textAlign:TextAlign.center,style:AppTextStyles.titleMedium),const SizedBox(height:AppDimens.spacingSm),const Text('Thêm nhà hoặc nơi làm việc để theo dõi sự cố xung quanh.',textAlign:TextAlign.center,style:AppTextStyles.bodyMedium)]):ListView.separated(padding:const EdgeInsets.fromLTRB(AppDimens.spacingMd,AppDimens.spacingSm,AppDimens.spacingMd,96),itemCount:items.length,itemBuilder:(_,i){final a=items[i];return InterestedAreaCard(area:a,onTap:()=>context.push(AppRoutes.interestedAreaDetailPath(a.id),extra:a),onEdit:()=>editor(context,ref,a),onDelete:()async{await ref.read(interestedAreasProvider.notifier).remove(a.id);});},separatorBuilder:(_,__)=>const SizedBox(height:AppDimens.spacingBase)))));}}
